// DCEP1 — pharmacy, third year: the Tunisian programme.
//
// The Faculté de pharmacie de Monastir's third year, as its students publish
// it on Pharmask (sites.google.com/view/pharmasktn › Externat › DCEP1). The
// page embeds one Drive folder, «3ème Année Pharmacie»
// (1IUZeRveGsbw5ja2pLveA5oCOMz2msmt0), shared «anyone with the link» and read
// off each folder's public listing — metadata only, nothing in it touched.
//
// A student reads this year in FMPOS's programme (dcep1.js) or in this one,
// chosen on الدراسة. Same shape as tn-dcep3.js: each subject's newest
// complete edition is its lectures, the older editions, résumés, exams, TD
// and TP are sections. CC1 is «MED.INFLA» and CC2 «MED.DIGE» in the
// faculty's own course codes, printed on every handout.
// Left out: Office lock files, the planification, Anki decks, native Google
// Docs and a .mol model.
//
// Every id starts `tn-` (lib/data.js, isTunisian).

